-- M8 (Phase 1, P1-11): the official school list (owner-supplied workbook "LIST OF BOARDING
-- GE, TSS AND PROFESSIONAL SCHOOLS ... 2024": sheets Boarding S1, Boarding S4, Day schools
-- S1 & S4 — 1974 schools, one row per school_code; rows repeated per combination were
-- collapsed by code, none conflicting).
--
-- Data only, ONE PostgreSQL DO statement (atomic: any error rolls back everything).
--   1. Existing schools without a code whose normalised name matches exactly ONE official
--      school (and no other uncoded school has that normalised name) ADOPT its code,
--      province, district, sector and ownership. Their id, name and students are unchanged.
--   2. Every other official school is inserted (official name; shared names get
--      ' — District[, Sector]' so School.name stays unique). Codes already present are skipped.
--   3. Uncoded schools that matched nothing, or ambiguously, are left as they are
--      (reported in the audit summary; an Administrator reassigns their students).
-- Province = the first digit of the code: 1 Kigali City, 2 Southern, 3 Western, 4 Northern,
-- 5 Eastern (matches all 30 districts of the list).
-- Idempotent: re-running adopts and inserts nothing new. Existing ids are never changed;
-- no school is merged or deleted; TeacherSchoolAssignment rows are not touched.
-- Normalised name = lower case, common accents removed, every non-alphanumeric run → one
-- space, trimmed (same as src/schools/school-key.ts).
-- Rollback: docs/migrations/20261121000700_official_school_list.rollback.sql
DO $$
DECLARE
  adopted   int := 0;
  inserted  int := 0;
  unmatched int := 0;
BEGIN
  DROP TABLE IF EXISTS pg_temp.official_school;
  CREATE TEMP TABLE official_school (code text PRIMARY KEY, official text NOT NULL, display text NOT NULL,
                                     province text NOT NULL, district text NOT NULL, sector text NOT NULL, ownership text NOT NULL, key text);
  UPDATE official_school SET key = trim(regexp_replace(translate(lower(official),
    'àáâäãåçèéêëìíîïñòóôöõùúûüýÿ', 'aaaaaaceeeeiiiinooooouuuuyy'), '[^a-z0-9]+', ' ', 'g'));

  -- 1. Adopt: unambiguous exact matches only.
  WITH ex AS (
    SELECT "id", trim(regexp_replace(translate(lower("name"),
      'àáâäãåçèéêëìíîïñòóôöõùúûüýÿ', 'aaaaaaceeeeiiiinooooouuuuyy'), '[^a-z0-9]+', ' ', 'g')) AS k
      FROM "School" WHERE "code" IS NULL
  ), m AS (
    SELECT ex."id", o.code FROM ex JOIN official_school o ON o.key = ex.k
     WHERE (SELECT count(*) FROM official_school o2 WHERE o2.key = ex.k) = 1
       AND (SELECT count(*) FROM ex e2 WHERE e2.k = ex.k) = 1
       AND NOT EXISTS (SELECT 1 FROM "School" s WHERE s."code" = o.code)
  )
  UPDATE "School" s SET "code" = o.code, "province" = o.province, "district" = o.district, "sector" = o.sector,
                        "ownership" = o.ownership, "nameKey" = o.key
    FROM m JOIN official_school o ON o.code = m.code
   WHERE s."id" = m."id";
  GET DIAGNOSTICS adopted = ROW_COUNT;

  -- 2. Insert the rest (a display name already taken by an uncoded school gets ' (code)').
  SELECT gen_random_uuid()::text,
         CASE WHEN EXISTS (SELECT 1 FROM "School" x WHERE x."name" = o.display) THEN o.display || ' (' || o.code || ')' ELSE o.display END,
         o.sector || ', ' || o.district, o.code, o.province, o.district, o.sector, o.ownership, o.key, CURRENT_TIMESTAMP
    FROM official_school o
   WHERE NOT EXISTS (SELECT 1 FROM "School" s WHERE s."code" = o.code);
  GET DIAGNOSTICS inserted = ROW_COUNT;

  SELECT count(*) INTO unmatched FROM "School" WHERE "code" IS NULL;
  IF adopted > 0 OR inserted > 0 THEN
    VALUES (gen_random_uuid()::text, 'OFFICIAL_SCHOOL_LIST_LOADED', 'School',
            jsonb_build_object('adopted', adopted, 'inserted', inserted, 'uncodedRemaining', unmatched, 'officialSchools', 1974),
            CURRENT_TIMESTAMP);
  END IF;
  RAISE NOTICE 'Official school list: % adopted, % inserted, % uncoded schools remain.', adopted, inserted, unmatched;
  DROP TABLE official_school;
END $$;
